script:
frappe.ui.form.on("Patient Encounter", {
    refresh(frm) {
    },

    validate(frm) {
        let rows = frm.doc.custom_dental_services || [];

        rows.forEach(function(row) {
            if (!row.dental_service)
                return;

            frappe.db.get_doc("Dental Service", row.dental_service)
                .then(service => {
                    if (
                        service.requires_tooth &&
                        !row.tooth_area
                    ) {
                        frappe.throw(
                            __("Please enter Tooth / Area for {0}",
                                [service.service_name]
                            )
                        );
                    }
                });
        });
    }
});


frappe.ui.form.on("Clinify Encounter Service", {

    dental_service(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row.dental_service)
            return;

        frappe.db.get_doc(
            "Dental Service",
            row.dental_service
        ).then(service => {

            frappe.model.set_value(
                cdt,
                cdn,
                "qty",
                service.default_qty || 1
            );

        });

    }

});
